// After a queued head leaves outside a window flip (its wait timer fires or
// its signal aborts), the requests behind it must be retried at once. Only
// entries already holding a COMPLETE reservation in the current pool window
// can flow: their quota was charged and feasibility-checked at gather time,
// so committing them moves no quota and performs no overtaking. The walk
// stops at the first live entry that is not fully held (a blocked head frees
// no room, so such an entry still cannot fit) and never gathers anew —
// mid-window re-gathering, like every adjustment, never grants early.
function drainHeld(r) {
  const q = r.queue;
  let i = r.head;
  for (; i < q.length; i += 1) {
    const entry = q[i];
    if (entry.removed) continue;
    if (!entry.holdsHeld || !entry.whole) break;
    settleEntry(entry, 'granted');
  }
  // The walk stopped (or ran out): every slot before i is removed, so the
  // head can move there permanently — re-scans across drains then total
  // O(queue length) amortized rather than quadratic.
  r.head = i;
  while (r.head < q.length && q[r.head].removed) r.head += 1;
  if (r.head > 32 && r.head * 2 >= q.length) {
    r.queue = q.slice(r.head);
    r.head = 0;
  }
  recomputeMinDeadlineFor(r);
}

