// After a queued head leaves outside a window flip (its wait timer fires,
// its signal aborts, a shrink refuses it, or a reparent settles it), the
// requests behind it must be retried at once. The walk follows arrival
// order and commits every prefix entry it can gather whole against the
// CURRENT pool, stopping at the first that cannot — an entry with no hold
// could not have gathered against this same pool state (the departed head
// freed nothing), and overtaking is the pool flip's job. The retry moves
// no rollback counter: a failed attempt simply keeps the entry queued and
// the next window flip gathers it again. Every entry leaves the queue at
// most once and the stopping index becomes the new head, so the total work
// across drains is amortized linear.
function drainHeld(r) {
  const q = r.queue;
  let i = r.head;
  for (; i < q.length; i += 1) {
    const entry = q[i];
    if (entry.removed) continue;
    if (!entry.holdsHeld) break;
    if (entry.holdsHeld) releaseHolds(entry);
    let ok;
    if (entry.combo) {
      ok = tryGather(entry, buildSegs(entry.comboGates, (g) => entry.comboUnits.get(g)));
    } else {
      ok = tryGatherOne(entry, entry.owner, entry.units);
    }
    if (!ok) break;
    settleEntry(entry, 'granted');
  }
  // Every slot before i is now removed; pin the head there permanently so
  // re-scans across drains never go quadratic.
  r.head = i;
  while (r.head < q.length && q[r.head].removed) r.head += 1;
  if (r.head > 32 && r.head * 2 >= q.length) {
    r.queue = q.slice(r.head);
    r.head = 0;
  }
  recomputeMinDeadlineFor(r);
