});

test('repeated head withdrawals keep releasing assembled requests in arrival order', async () => {
  const root = createGate({ limit: 4, windowMs: 10000, maxWaitMs: 5000 });
  await root.acquire(2); // pool 2/4
  const handles = [];
  // Ten cycles: a blocked 3-unit head (holds nothing) followed by an
  // assembled 2-unit request (2+2=4); cancelling the head releases the
  // assembled request immediately. Exercises queue compaction and the retry
  // prefix across many cuts without a single window flip.
  for (let i = 0; i < 10; i += 1) {
    const ac = new AbortController();
    const pHead = root.acquire(3, ac.signal).then(() => null, (e) => e);
    const pLater = root.acquire(2);
    ac.abort();
    assert.equal((await pHead).code, 'CANCELLED');
    handles.push(await pLater);
    handles.pop().release(); // free the 2 units again for the next cycle
  }
  const s = root.stats();
  assert.equal(s.cancelled, 10);
  assert.equal(s.granted, 11); // the initial occupation plus ten retried grants
  assert.equal(s.waiting, 0);
  assert.equal(s.reserved, 0);
});

