  // Head combo expires after 20ms and holds nothing.
  const pHead = root.acquireAll([{ gate: a, units: 4 }]);
  // Patient later single already holds its complete 2-unit reservation.
  const pLater = root.acquire(2);
  const headErr = await pHead.then(() => null, (e) => e);
  assert.equal(headErr.code, 'WAIT_EXPIRED');
  const hLater = await pLater; // released by the retry, not by a window flip
  assert.equal(root.stats().expired, 1);
  assert.equal(root.stats().granted, 2);
  hLater.release();
});

test('at one moment expiry beats the retry grant after a head cancellation', async (t) => {
  const root = createGate({ limit: 2, windowMs: 10000, maxWaitMs: 5000 });
  const soon = createGate({ limit: 2, windowMs: 10000, maxWaitMs: 30, parent: root });
  await root.acquire(1); // pool 1/2
  const ac = new AbortController();
  const pHead = root.acquire(2, ac.signal); // 1+2>2: blocked head, holds nothing
  // Middle request has a 30ms cap and holds its one unit; last request is
  // patient and also holds one unit (1+1=2).
  const pMiddle = soon.acquire(1).then(() => 'granted', (e) => e.code);
  const pLast = root.acquire(1).then(() => 'granted', (e) => e.code);
  const realNow = Date.now();
  t.mock.method(Date, 'now', () => realNow + 1000); // past the middle cap, before the last
  ac.abort(); // head withdrawal triggers the retry
  assert.equal(await pMiddle, 'WAIT_EXPIRED'); // expiry settled before the grant
  assert.equal(await pLast, 'granted'); // the assembled later request still flows
  assert.equal(root.stats().expired, 1);
  assert.equal(soon.stats().expired, 1); // the entry-gate owns the expiry count
  assert.equal(root.stats().granted, 2);
});

test('a shrink-refused head releases a fully-assembled later request in the same cut', async () => {
