import { createGate } from '/mnt/c/claude_gsb/cla10/solverB/task018/src/index.js';

// Stress: large live queue + repeated head cancellations must not go quadratic.
const root = createGate({ limit: 2, windowMs: 10_000_000, maxWaitMs: 10_000_000 });
await root.acquire(2); // pool full for the whole test
const N = 20000;
const heads = [];
// Alternate blocked heads (abortable) and permanent blocked waiters.
for (let i = 0; i < N; i += 1) {
  const ac = new AbortController();
  heads.push(root.acquire(3, ac.signal).catch(() => {}));
  root.acquire(1).catch(() => {}); // permanent waiter behind, holds nothing
  heads[heads.length - 1].ac = ac;
}
const t0 = process.hrtime.bigint();
for (const p of heads) p.ac.abort();
await Promise.all(heads);
const ms = Number(process.hrtime.bigint() - t0) / 1e6;
console.log(`${N} head aborts interleaved with ${N} live waiters: ${ms.toFixed(1)} ms`);
if (ms > 4000) { console.log('TOO SLOW — likely quadratic'); process.exit(1); }
console.log('cancelled:', root.stats().cancelled, 'waiting units:', root.stats().waiting);

// Stress 2: a long prefix granted by ONE drain.
const g2 = createGate({ limit: N, windowMs: 10_000_000, maxWaitMs: 10_000_000 });
const ac2 = new AbortController();
g2.acquire(N + 1, ac2.signal).catch(() => {}); // blocked head
const ps = [];
for (let i = 0; i < N; i += 1) ps.push(g2.acquire(1));
const t1 = process.hrtime.bigint();
ac2.abort();
await Promise.all(ps);
const ms2 = Number(process.hrtime.bigint() - t1) / 1e6;
console.log(`one drain granting ${N} assembled waiters: ${ms2.toFixed(1)} ms, granted=${g2.stats().granted}`);
EOF
node /tmp/qg/stress.mjs

